(function(root){
 'use strict';
 const S=root.Season||(typeof require==='function'?require('./season.js'):null),F=root.Football||(typeof require==='function'?require('./engine.js'):null),Staff=root.Staff||(typeof require==='function'?require('./staff.js'):null),Board=root.OwnerBoard||(typeof require==='function'?require('./owner-board.js'):null),Opp=root.Opposition||(typeof require==='function'?require('./opposition.js'):null);
 const focuses=[['technique','기술'],['pace','속도'],['fitness','지구력'],['recovery','회복']],mean=rows=>rows.length?rows.reduce((sum,v)=>sum+v,0)/rows.length:0;
 function training(s){return focuses.map(([focus,label])=>{const p=S.trainingPreview(s,focus);return {focus,label,available:p.available,reason:p.reason,changed:p.rows.filter(r=>r.gain>0&&!r.skipped).length,energyBefore:mean(p.rows.map(r=>r.energyBefore)),energyAfter:mean(p.rows.map(r=>r.energyAfter)),tired:p.rows.filter(r=>r.starting&&r.energyAfter<70).length};});}
 function read(s){
  if(!s?.squad||!s.league||!Array.isArray(s.results))return {valid:false};
  const finished=S.ready(s),m=s.match,players=Object.values(s.squad),live=p=>m?.players?.[p.id]?.identity===p.identity?m.players[p.id]:p,available=players.filter(p=>F.isAvailable(live(p))),starting=(m?.lineup||[]).map(id=>s.squad[id]).filter(Boolean),tired=starting.filter(p=>live(p).energy<70),injured=players.filter(p=>!F.isAvailable(live(p))),table=S.standings(s),own=table.find(p=>p.id===S.own),board=Board.read(s),active=Staff.roles.map(role=>Staff.active(s,role)).filter(Boolean),expiring=active.filter(c=>c.remaining<=2),opponent=finished?null:Opp.read(s),fixture=finished?null:S.fixtureFor(s),last=s.results.filter(r=>r.home===S.own||r.away===S.own).slice(-5).map(r=>{const goals=r.home===S.own?[...r.goals]:[r.goals[1],r.goals[0]],club=S.club(r.home===S.own?r.away:r.home);return {opponent:club.short,goals,outcome:goals[0]>goals[1]?'win':goals[0]===goals[1]?'draw':'loss'};});
  const trainingOpen=!finished&&S.trainingPreview(s,'recovery').available,promise=board.active;
  const reports=[
   {target:'squad-health',title:'선발 몸 상태',value:starting.length?Math.round(mean(starting.map(p=>live(p).energy)))+' 체력':'선발 대기',tone:tired.length||injured.length?'warning':'good',note:tired.length?'선발 '+tired.length+'명 체력 70 미만 · 회복/교체 비교':injured.length?'출전 불가 '+injured.length+'명 · 대체 선수 확인':'선발 체력과 출전 가능 여부를 확인하세요.'},
   {target:'training-card',title:'이번 주 훈련',value:finished?'시즌 종료':s.trained?'완료':trainingOpen?'선택 가능':'경기 준비 대기',tone:trainingOpen?'ready':'neutral',note:finished?'현재 선수 상태와 시즌 기록을 유지합니다.':s.trained?'팀·개인 공유 1회 사용 · 다음 리그 준비 때 열림':trainingOpen?'기술 향상과 체력 부담을 비교한 뒤 실행':'리그 경기 시작 전 주 1회 · 대회에서는 휴식'},
   {target:'staff-panel',title:'코치 계약',value:active.length+' / 5명',tone:expiring.length?'warning':'neutral',note:expiring.length?'계약 '+expiring.length+'명 2경기 이내 만료 · 연장 검토':(5-active.length)+'역할 공석 · 영입금과 리그 주급 확인'},
   {target:'owner-board-panel',title:'이사회·약속',value:String(board.confidence?.score??board.trust)+' 신임',tone:(board.confidence?.score??board.trust)<35?'warning':'neutral',note:promise?promise.label+' · '+promise.progress+'/'+promise.target+promise.unit+' · '+promise.end+'R까지':'진행 약속 없음 · 면담 주제와 투자 조건 확인'}
  ];
  return {valid:true,finished,year:s.year,division:s.league.division,phase:m?.phase||'complete',round:s.round,rounds:S.roundCount(s),rank:own?.played?own.rank:null,points:own?.points??0,average:mean(players.map(p=>p[S.primaryKey(p)])),energy:mean(available.map(p=>live(p).energy)),available:available.length,total:players.length,balance:s.finance.balance,reports,last,fixture:fixture?{home:fixture.home===S.own,club:opponent.club,formation:opponent.plan.formation,keyPlayer:opponent.keyPlayer,comparisons:opponent.comparisons,recent:[...opponent.recent]}:null};
 }
 const api={read,training};root.PreparationDesk=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
